meta.css:
:root { --acc: #0f766e; --acc-hover: #115e59; --acc-soft: #f0fdfa; --acc-border: #99f6e4; --pro: #6d28d9; }
[data-theme="dark"], :root[data-theme="auto"] { --acc: #2dd4bf; --acc-hover: #5eead4; --acc-soft: #042f2e; --acc-border: #115e59; --pro: #a78bfa; }
@media (prefers-color-scheme: light) {
  :root[data-theme="auto"] { --acc: #0f766e; --acc-hover: #115e59; --acc-soft: #f0fdfa; --acc-border: #99f6e4; --pro: #6d28d9; }
}
[data-theme="light"] { --acc: #0f766e; --acc-hover: #115e59; --acc-soft: #f0fdfa; --acc-border: #99f6e4; --pro: #6d28d9; }
.bar { border-bottom: 2px solid var(--pro); }
.bar-title::after { content: " · специалисту"; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--pro); font-weight: 700; }
